function updateMapLeaders(){document.querySelectorAll('.map-pin').forEach(el=>{const span=el.querySelector('span'),line=el.querySelector('.map-leader');if(!span||!line||!span.offsetWidth)return;const x=THREE.MathUtils.clamp(10,span.offsetLeft,span.offsetLeft+span.offsetWidth),y=THREE.MathUtils.clamp(10,span.offsetTop,span.offsetTop+span.offsetHeight),dx=x-10,dy=y-10;line.style.width=`${Math.hypot(dx,dy)}px`;line.style.transform=`rotate(${Math.atan2(dy,dx)}rad)`;});}
