function characterReferences(data){const related=lore.visualReferences?.[data.id==='smaug'?'erebor':['elrond','gandalf'].includes(data.id)?'rivendell':data.id==='legolas'?'thranduil':'shire'],images=data.id==='smaug'?(related?.images||[]).filter(i=>i.title.includes('Smaug')):(related?.images||[]).slice(0,1);return `<p class="story-intro">${esc(data.summary)}</p>${images.map(im=>`<figure class="reference-card"><img src="${esc(referenceAssets[im.url]||im.url)}" alt="${esc(im.title)}" loading="lazy"><figcaption>${esc(im.title)}<br>${esc(im.credit)}<br><a href="${esc(im.pageUrl)}" target="_blank" rel="noopener noreferrer">Świat postaci — ilustracja źródłowa</a></figcaption></figure>`).join('')}<ul class="reference-details">${(data.facts||[]).map(t=>`<li>${esc(t)}</li>`).join('')}</ul><div class="margin-note"><p>${(data.sources||related?.sources||[]).map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a>`).join('<br>')}</p></div>`;}
